// ===================================================================
// Monta o evento pra Meta: normaliza, hasheia e traduz o sinal.
// NAO precisa mexer aqui — a configuracao vem do no anterior.
// ===================================================================
const crypto = require('crypto');
const sha = (v) => v ? crypto.createHash('sha256').update(v).digest('hex') : null;
const normPhone = (p) => String(p || '').replace(/\D/g, '');
const normEmail = (e) => String(e || '').trim().toLowerCase();

// Traducao: o sinal que o Pulsefy manda -> o nome do evento na Meta.
const MAPA = {
  qualificado: 'Lead',
  comprou: 'Purchase',
  recorrente: 'Purchase',
  sem_perfil: 'LeadSemPerfil',
  curioso: 'LeadCurioso',
  concorrente: 'LeadConcorrente',
};

const cfg = $('Configuração do cliente').first().json;
const body = $json.body || $json;

const evento = String(body.evento || '').toLowerCase();
const eventName = MAPA[evento];
if (!eventName) { throw new Error('evento desconhecido: "' + evento + '" — confira o campo evento no workflow do Pulsefy'); }

const phoneHash = sha(normPhone(body.phone));
const emailHash = sha(normEmail(body.email));
if (!phoneHash && !emailHash) { throw new Error('lead sem telefone nem e-mail — a Meta nao consegue casar a pessoa'); }

const user_data = {};
if (phoneHash) user_data.ph = [phoneHash];
if (emailHash) user_data.em = [emailHash];
if (body.ctwaClid) user_data.ctwa_clid = String(body.ctwaClid);

const custom_data = {};
if (eventName === 'Purchase') {
  custom_data.value = Number(String(body.valor || '0').replace(',', '.'));
  custom_data.currency = body.moeda || 'BRL';
}

// event_id: impede a mesma venda/lead de contar duas vezes se o webhook repetir.
const dedupBase = eventName === 'Purchase'
  ? evento + ':' + (body.contactId || '') + ':' + (body.dealId || body.valor || '')
  : evento + ':' + (body.contactId || '');
const event_id = sha(dedupBase);

const evento_data = {
  event_name: eventName,
  event_time: Math.floor(Date.now() / 1000),
  action_source: 'system_generated',
  event_id: event_id,
  user_data: user_data,
};
if (Object.keys(custom_data).length) evento_data.custom_data = custom_data;

const payload = { data: [evento_data], access_token: cfg.TOKEN };
const tec = String(cfg.TEST_EVENT_CODE || '').trim();
if (tec && !tec.startsWith('TESTxxxx')) payload.test_event_code = tec;

return { json: { pixelId: cfg.PIXEL_ID, payload: payload } };
